"""
Audit Trail Module

Provides an immutable, append-only log of all agent interactions.
Uses SQLite with triggers to enforce immutability.
"""

from typing import Optional, Dict, Any
from datetime import datetime
import sqlite3
import json
import hashlib
import os
from pathlib import Path


class AuditError(Exception):
    """Custom exception for audit log failures."""
    def __init__(self, message: str, code: str = "AUDIT_FAILED"):
        self.message = message
        self.code = code
        super().__init__(self.message)


class AuditLogger:
    """
    Immutable audit logger for agent interactions.
    Stores logs in SQLite with triggers preventing modification or deletion.
    """

    def __init__(self, db_path: str = "swarm_audit.db"):
        self.db_path = db_path
        self._initialize_database()

    def _initialize_database(self):
        """Create the audit table and immutability triggers."""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        # Create audit table
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_id TEXT UNIQUE NOT NULL,
                timestamp TEXT NOT NULL,
                sender_id TEXT NOT NULL,
                receiver_id TEXT NOT NULL,
                action TEXT NOT NULL,
                payload_hash TEXT NOT NULL,
                metadata TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)

        # Create trigger to prevent UPDATE
        cursor.execute("""
            CREATE TRIGGER IF NOT EXISTS prevent_audit_update
            BEFORE UPDATE ON audit_log
            BEGIN
                SELECT RAISE(ABORT, 'Audit log is immutable: UPDATE not allowed');
            END
        """)

        # Create trigger to prevent DELETE
        cursor.execute("""
            CREATE TRIGGER IF NOT EXISTS prevent_audit_delete
            BEFORE DELETE ON audit_log
            BEGIN
                SELECT RAISE(ABORT, 'Audit log is immutable: DELETE not allowed');
            END
        """)

        # Create index for efficient querying
        cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_audit_timestamp
            ON audit_log(timestamp)
        """)
        cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_audit_sender
            ON audit_log(sender_id)
        """)

        conn.commit()
        conn.close()

    def log_interaction(
        self,
        sender_id: str,
        receiver_id: str,
        action: str,
        payload: Optional[Dict[str, Any]] = None,
        metadata: Optional[Dict[str, Any]] = None
    ) -> str:
        """
        Log an agent interaction to the immutable audit trail.

        Args:
            sender_id: ID of the sending agent
            receiver_id: ID of the receiving agent
            action: The action performed
            payload: Optional payload data (will be hashed)
            metadata: Optional metadata dictionary

        Returns:
            Event ID for the logged interaction

        Raises:
            AuditError: If logging fails
        """
        try:
            # Generate event ID from content hash
            event_content = f"{sender_id}:{receiver_id}:{action}:{datetime.utcnow().isoformat()}"
            event_id = hashlib.sha256(event_content.encode()).hexdigest()[:32]

            # Compute payload hash
            payload_str = json.dumps(payload or {}, sort_keys=True)
            payload_hash = hashlib.sha256(payload_str.encode()).hexdigest()

            # Prepare metadata
            metadata_str = json.dumps(metadata or {})

            # Insert into database
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            cursor.execute("""
                INSERT INTO audit_log (event_id, timestamp, sender_id, receiver_id, action, payload_hash, metadata)
                VALUES (?, ?, ?, ?, ?, ?, ?)
            """, (
                event_id,
                datetime.utcnow().isoformat(),
                sender_id,
                receiver_id,
                action,
                payload_hash,
                metadata_str
            ))
            conn.commit()
            conn.close()

            return event_id

        except sqlite3.Error as e:
            raise AuditError(f"Failed to log interaction: {str(e)}", "DB_ERROR")

    def query_logs(
        self,
        sender_id: Optional[str] = None,
        receiver_id: Optional[str] = None,
        action: Optional[str] = None,
        start_time: Optional[str] = None,
        end_time: Optional[str] = None,
        limit: int = 100
    ) -> list:
        """
        Query the audit log with optional filters.

        Args:
            sender_id: Filter by sender
            receiver_id: Filter by receiver
            action: Filter by action
            start_time: ISO format start time
            end_time: ISO format end time
            limit: Maximum number of results

        Returns:
            List of log entries as dictionaries
        """
        query = "SELECT * FROM audit_log WHERE 1=1"
        params = []

        if sender_id:
            query += " AND sender_id = ?"
            params.append(sender_id)
        if receiver_id:
            query += " AND receiver_id = ?"
            params.append(receiver_id)
        if action:
            query += " AND action = ?"
            params.append(action)
        if start_time:
            query += " AND timestamp >= ?"
            params.append(start_time)
        if end_time:
            query += " AND timestamp <= ?"
            params.append(end_time)

        query += " ORDER BY timestamp DESC LIMIT ?"
        params.append(limit)

        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        cursor.execute(query, params)
        rows = cursor.fetchall()
        conn.close()

        return [dict(row) for row in rows]

    def verify_integrity(self, event_id: str) -> bool:
        """
        Verify the integrity of a specific log entry by recomputing its hash.

        Args:
            event_id: The event ID to verify

        Returns:
            True if the entry is intact, False otherwise
        """
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM audit_log WHERE event_id = ?", (event_id,))
        row = cursor.fetchone()
        conn.close()

        if not row:
            return False

        # Recompute expected event ID
        expected_content = f"{row[3]}:{row[4]}:{row[5]}:{row[2]}"
        expected_id = hashlib.sha256(expected_content.encode()).hexdigest()[:32]

        return row[1] == expected_id